1	package org.jsoup.internal;
2	
3	import org.jsoup.Progress;
4	import org.jsoup.helper.Validate;
5	import org.jspecify.annotations.Nullable;
6	
7	import java.io.BufferedInputStream;
8	import java.io.FilterInputStream;
9	import java.io.IOException;
10	import java.io.InputStream;
11	import java.net.SocketTimeoutException;
12	import java.nio.ByteBuffer;
13	
14	import static org.jsoup.internal.SharedConstants.DefaultBufferSize;
15	
16	/**
17	 * A jsoup internal class (so don't use it as there is no contract API) that enables controls on a buffered input stream,
18	 * namely a maximum read size, and the ability to Thread.interrupt() the read.
19	 */
20	// reimplemented from ConstrainableInputStream for JDK21 - extending BufferedInputStream will pin threads during read
21	public class ControllableInputStream extends FilterInputStream {
22	    private final SimpleBufferedInput buff; // super.in, but typed as SimpleBufferedInput
23	    private int maxSize;                    // logical cap exposed to callers (0 == unlimited)
24	    private long startTime;                 // start time for timeout checks, nanos
25	    private long timeout = 0;               // optional max time of request
26	    private int remaining;                  // how many bytes may still be returned to caller under the current cap
27	    private int markPos;                    // logical readPos snapshot for InputStream.mark/reset (not a buffer cursor)
28	    private boolean interrupted;            // true if Thread.interrupted() was detected, used to latch interrupted state
29	    private boolean truncated;              // true if there is content beyond the body cap
30	    private boolean allowClose = true;      // for cases where we want to re-read the input, can ignore .close() from the parser
31	    private final byte[] singleByte = new byte[1]; // avoids allocation when routing single-byte reads through controls
32	
33	    // if we are tracking progress, will have the expected content length and progress callback state
34	    private @Nullable ProgressState<?> progress;
35	    private int contentLength = -1;         // declared content length for progress; -1 == unknown
36	    private boolean successful = true;     // whether the response was a successful status; failures never report completion
37	    private int readPos = 0;                // logical amount read; can move backwards on reset()
38	    private int highWater = 0;              // furthest logical position ever read; progress never reports below this
39	    private int lastEmitted = -1;           // last processed value emitted, to suppress duplicate re-read events
40	    private boolean emittedInitial = false; // the initial (0, total, 0%) event has been emitted
41	    private boolean completed = false;      // the terminal completion event has been emitted
42	
43	    private ControllableInputStream(SimpleBufferedInput in, int maxSize) {
44	        super(in);
45	        Validate.isTrue(maxSize >= 0);
46	        buff = in;
47	        this.maxSize = maxSize;
48	        remaining = maxSize;
49	        markPos = -1;
50	        startTime = System.nanoTime();
51	    }
52	
53	    /**
54	     * If this InputStream is not already a ControllableInputStream, let it be one.
55	     * @param in the input stream to (maybe) wrap. A {@code null} input will create an empty wrapped stream.
56	     * @param maxSize the maximum size to allow to be read. 0 == infinite.
57	     * @return a controllable input stream
58	     */
59	    public static ControllableInputStream wrap(@Nullable InputStream in, int maxSize) {
60	        // bufferSize currently unused; consider implementing as a min size in the SoftPool recycler
61	        if (in instanceof ControllableInputStream)
62	            return (ControllableInputStream) in;
63	        else
64	            return new ControllableInputStream(new SimpleBufferedInput(in), maxSize);
65	    }
66	
67	    /**
68	     * If this InputStream is not already a ControllableInputStream, let it be one.
69	     * @param in the input stream to (maybe) wrap
70	     * @param bufferSize the buffer size to use when reading
71	     * @param maxSize the maximum size to allow to be read. 0 == infinite.
72	     * @return a controllable input stream
73	     */
74	    public static ControllableInputStream wrap(InputStream in, int bufferSize, int maxSize) {
75	        // todo - bufferSize currently unused; consider implementing as a min size in the SoftPool recycler; or just deprecate if always DefaultBufferSize
76	        return wrap(in, maxSize);
77	    }
78	
79	    @Override
80	    public int read() throws IOException {
81	        int read = read(singleByte, 0, 1); // route through the controlled read, so caps and progress account for single-byte reads
82	        return read == -1 ? -1 : singleByte[0] & 0xff;
83	    }
84	
85	    @Override
86	    public int read(byte[] b, int off, int len) throws IOException {
87	        emitInitialProgress();
88	
89	        boolean capped = maxSize != 0;
90	        if (interrupted)
91	            return -1;
92	        if (Thread.currentThread().isInterrupted()) {
93	            // interrupted latches, because parse() may call twice
94	            interrupted = true;
95	            return -1;
96	        }
97	        if (capped && remaining <= 0) {
98	            if (checkTruncated()) return -1; // more content exists beyond the cap: this is a truncation, not an end of entity
99	            complete(); // entity ended exactly on the cap
100	            return -1;
101	        }
102	
103	        if (capped && len > remaining)
104	            len = remaining; // don't read more than desired, even if available
105	        if (capped) buff.capRemaining(remaining);
106	        else buff.uncap();
107	
108	        while (true) { // loop trying to read until we get some data or hit the overall timeout, if we have one
109	            if (expired())
110	                throw new SocketTimeoutException("Read timeout");
111	
112	            try {
113	                final int read = super.read(b, off, len);
114	                if (read == -1) { // the underlying entity genuinely ended
115	                    complete();
116	                } else {
117	                    if (capped && read > 0) {
118	                        remaining -= read; // track bytes returned to the caller
119	                    }
120	                    // todo: use long progress values in the public API; saturate until that is available
121	                    readPos = read > Integer.MAX_VALUE - readPos ? Integer.MAX_VALUE : readPos + read;
122	                    emitProgress();
123	                }
124	                return read;
125	            } catch (SocketTimeoutException e) {
126	                if (expired() || timeout == 0)
127	                    throw e;
128	            }
129	        }
130	    }
131	
132	    @Override
133	    public long skip(long requested) throws IOException {
134	        // implemented here so our cap accounting and progress stay aligned with actual reads
135	        if (requested <= 0) return 0;
136	
137	        byte[] skipBuffer = SimpleBufferedInput.BufferPool.borrow();
138	        long skipped = 0;
139	        try {
140	            while (skipped < requested) {
141	                int read = read(skipBuffer, 0, (int) Math.min(requested - skipped, skipBuffer.length));
142	                if (read == -1) break;
143	                skipped += read;
144	            }
145	            return skipped;
146	        } finally {
147	            SimpleBufferedInput.BufferPool.release(skipBuffer);
148	        }
149	    }
150	
151	    @Override
152	    public boolean markSupported() {
153	        return true;
154	    }
155	
156	    /**
157	     * Reads this inputstream to a ByteBuffer. The supplied max may be less than the inputstream's max, to support
158	     * reading just the first bytes.
159	     */
160	    public static ByteBuffer readToByteBuffer(InputStream in, int max) throws IOException {
161	        Validate.isTrue(max >= 0, "maxSize must be 0 (unlimited) or larger");
162	        Validate.notNull(in);
163	        final boolean capped = max > 0;
164	        final byte[] readBuf = SimpleBufferedInput.BufferPool.borrow(); // Share the same byte[] pool as SBI
165	        final int outSize = capped ? Math.min(max, DefaultBufferSize) : DefaultBufferSize;
166	        ByteBuffer outBuf = ByteBuffer.allocate(outSize);
167	
168	        try {
169	            int remaining = max;
170	            int read;
171	            while ((read = in.read(readBuf, 0, capped ? Math.min(remaining, DefaultBufferSize) : DefaultBufferSize)) != -1) {
172	                if (outBuf.remaining() < read) { // needs to grow
173	                    int newCapacity = (int) Math.max(outBuf.capacity() * 1.5, outBuf.capacity() + read);
174	                    ByteBuffer newBuffer = ByteBuffer.allocate(newCapacity);
175	                    outBuf.flip();
176	                    newBuffer.put(outBuf);
177	                    outBuf = newBuffer;
178	                }
179	                outBuf.put(readBuf, 0, read);
180	                if (capped) {
181	                    remaining -= read;
182	                    if (remaining <= 0) break;
183	                }
184	            }
185	            outBuf.flip(); // Prepare the buffer for reading
186	            return outBuf;
187	        } finally {
188	            SimpleBufferedInput.BufferPool.release(readBuf);
189	        }
190	    }
191	
192	    @SuppressWarnings("NonSynchronizedMethodOverridesSynchronizedMethod") // not synchronized in later JDKs
193	    @Override public void reset() throws IOException {
194	        if (markPos < 0) throw new IOException("Resetting to invalid mark");
195	        buff.rewindToMark();
196	        buff.clearMark();
197	        truncated = false;
198	        if (maxSize != 0) {
199	            remaining = maxSize - markPos;
200	            buff.capRemaining(remaining);
201	        } else {
202	            remaining = 0;
203	            buff.uncap();
204	        }
205	        readPos = markPos; // logical position rewinds; highWater keeps delivered progress monotonic across the re-read
206	        markPos = -1;
207	    }
208	
209	    @SuppressWarnings("NonSynchronizedMethodOverridesSynchronizedMethod")
210	    @Override public void mark(int readlimit) {
211	        markPos = readPos;
212	        buff.setMark();
213	    }
214	
215	    /**
216	     Check if the underlying InputStream has been read fully. There may still content in buffers to be consumed, and
217	     read methods may return -1 if hit the read limit.
218	     @return true if the underlying inputstream has been read fully.
219	     */
220	    public boolean baseReadFully() {
221	        return buff.baseReadFully();
222	    }
223	
224	    public void resetFullyRead() {
225	        buff.resetFullyRead();
226	    }
227	
228	    /**
229	     Get the max size of this stream (how far at most will be read from the underlying stream)
230	     * @return the max size
231	     */
232	    public int max() {
233	        return maxSize;
234	    }
235	
236	    public void max(int newMax) {
237	        remaining += newMax - maxSize; // update remaining to reflect the difference in the new maxsize
238	        if (remaining < 0) remaining = 0;
239	        if (newMax == 0 || newMax > maxSize) truncated = false;
240	        maxSize = newMax;
241	        if (newMax == 0) buff.uncap();
242	        else buff.capRemaining(remaining);
243	    }
244	
245	    /**
246	     Probes whether content remains beyond the configured cap, without pulling that content into the logical stream.
247	     @return true if the entity was truncated by the cap; false if the cap was reached at a genuine end of entity
248	     */
249	    public boolean checkTruncated() throws IOException {
250	        while (!truncated && maxSize != 0 && remaining <= 0) {
251	            if (expired()) throw new SocketTimeoutException("Read timeout");
252	            try {
253	                truncated = buff.hasMore();
254	                break;
255	            } catch (SocketTimeoutException e) {
256	                if (expired() || timeout == 0) throw e;
257	            }
258	        }
259	        return truncated;
260	    }
261	
262	    /**
263	     Returns whether content was found beyond the configured cap.
264	     */
265	    public boolean isTruncated() {
266	        return truncated;
267	    }
268	
269	    public void allowClose(boolean allowClose) {
270	        this.allowClose = allowClose;
271	    }
272	
273	    @Override public void close() throws IOException {
274	        if (allowClose) super.close();
275	    }
276	
277	    public ControllableInputStream timeout(long startTimeNanos, long timeoutMillis) {
278	        this.startTime = startTimeNanos;
279	        this.timeout = timeoutMillis * 1000000;
280	        return this;
281	    }
282	
283	    /**
284	     Emits the single initial progress event {@code (0, total, 0%)} on the first controlled read. A declared length
285	     of zero is an already-complete entity, so its one and only event is the terminal completion.
286	     */
287	    private void emitInitialProgress() {
288	        if (emittedInitial || progress == null) return;
289	        if (contentLength == 0) { // empty entity: nothing can ever be read, so complete immediately and exactly once
290	            complete();
291	            return;
292	        }
293	        emittedInitial = true;
294	        int processed = Math.max(readPos, highWater);
295	        highWater = processed;
296	        lastEmitted = processed;
297	        float percent = contentLength > 0 ? Math.min(100f, processed * 100f / contentLength) : 0f;
298	        progress.emit(processed, contentLength, percent);
299	    }
300	
301	    /**
302	     Emits an intermediate progress event, unless the logical position is being re-read after a reset, in which case
303	     the already-reported high-water position is held so that progress never moves backwards or repeats.
304	     */
305	    private void emitProgress() {
306	        ProgressState<?> progress = this.progress;
307	        if (progress == null) return;
308	        int processed = Math.max(readPos, highWater);
309	        highWater = processed;
310	        if (processed == lastEmitted) return; // re-reading buffered content after a reset: no new progress
311	        lastEmitted = processed;
312	        // calculate percent complete against the declared length; unknown length stays at 0
313	        float percent = contentLength > 0 ? processed * 100f / contentLength : 0f;
314	        // 100% is reserved for the single terminal event confirmed at end-of-entity; an intermediate read that
315	        // already meets (or exceeds, e.g. with a compressed declared length) the total reports just below it
316	        if (percent >= 100f) percent = Math.nextDown(100f);
317	        progress.emit(processed, contentLength, percent);
318	    }
319	
320	    /**
321	     Emits the exactly-once terminal completion event when the entity has been confirmed read to its end. Reaching a
322	     configured cap is not completion while further content exists; an I/O failure does not call this, so a failed
323	     read never reports completion. An unsuccessful response status may report the bytes actually delivered, but never
324	     a 100% completion.
325	     */
326	    private void complete() {
327	        highWater = Math.max(highWater, readPos);
328	        ProgressState<?> progress = this.progress;
329	        if (progress == null || completed) return;
330	        completed = true;
331	        emittedInitial = true;
332	        int processed = highWater;
333	        if (successful) {
334	            // once read to the end, an unknown length is resolved to the delivered length; a declared length is held
335	            int total = contentLength > 0 ? contentLength : processed;
336	            progress.emit(processed, total, 100f);
337	        } else {
338	            // unsuccessful status: report the actual partial delivery, but hold below completion and keep total as
339	            // declared (-1 when unknown) so that the caller never mistakes it for a successful completion
340	            float percent = contentLength > 0
341	                ? Math.min(Math.nextDown(100f), processed * 100f / contentLength)
342	                : 0f;
343	            progress.emit(processed, contentLength, percent);
344	        }
345	        this.progress = null; // detach: no later buffered hit may report another completion
346	    }
347	
348	    public <ProgressContext> ControllableInputStream onProgress(int contentLength, Progress<ProgressContext> callback, ProgressContext context) {
349	        return onProgress(contentLength, true, callback, context);
350	    }
351	
