        Method nextMethod = redirectMethod(res.statusCode, req.method());
        if (nextMethod != null && res.hasHeader(LOCATION) && req.followRedirects()) {
            if (nextMethod == req.method() && (req.body instanceof InputStream || needsMultipart(req)))
                throw new IOException("Cannot follow redirect with a streamed request body; disable followRedirects and resend with a fresh stream");

            if (nextMethod != req.method()) {
                req.method(nextMethod);
                req.data().clear();
                req.requestBody(null);
                for (String header : REDIRECT_CONTENT_HEADERS)
                    req.removeHeader(header);
            }

            String location = res.header(LOCATION);
            Validate.notNull(location);
            URL redir = StringUtil.resolve(req.url(), location);
            if (!sameOrigin(req.url(), redir)) {
                // remove sensitive headers; defense-in-depth against open redirects
                req.removeHeader("Authorization");
                req.removeHeader("Cookie");
                req.removeHeader("Cookie2");
                req.cookies().clear();
            }
            req.url(redir);

            return execute(req, res);
        }
        if ((res.statusCode < 200 || res.statusCode >= 400) && !req.ignoreHttpErrors())
                throw new HttpStatusException("HTTP error fetching URL", res.statusCode, req.url().toString());

        // check that we can handle the returned content type; if not, abort before fetching it
        String contentType = res.contentType();
        boolean isText = contentType != null && contentType.regionMatches(true, 0, "text/", 0, 5);
        boolean isXml = contentType != null && xmlContentTypeRxp.matcher(contentType).matches();

        if (contentType != null
                && !req.ignoreContentType()
                && !isText
                && !isXml
                )
            throw new UnsupportedMimeTypeException("Unhandled content type. Must be a text or XML media type",
                    contentType, req.url().toString());

        // switch to the XML parser if content type is xml and not parser not explicitly set
        if (isXml) {
            if (!req.parserDefined) req.parser(Parser.xmlParser());
        }

        res.charset = DataUtil.getCharsetFromContentType(res.contentType); // may be null, readInputStream deals with it
        // only a delivered successful (2xx/3xx) response may report completion; an error status body must
        // never signal 100% even when read to its end
        boolean successful = res.statusCode >= 200 && res.statusCode < 400;
        if (res.contentLength != 0 && req.method() != HEAD) { // -1 means unknown, chunked. sun throws an IO exception on 500 response with no content when trying to read body
            InputStream stream = executor.responseBody();
            boolean contentEncoded = res.hasHeaderWithValue(CONTENT_ENCODING, "gzip")
                || res.hasHeaderWithValue(CONTENT_ENCODING, "deflate");
            if (res.hasHeaderWithValue(CONTENT_ENCODING, "gzip"))
                stream = new GZIPInputStream(stream);
            else if (res.hasHeaderWithValue(CONTENT_ENCODING, "deflate"))
                stream = new InflaterInputStream(stream, new Inflater(true));

            res.bodyStream = ControllableInputStream.wrap(
                stream, DefaultBufferSize, req.maxBodySize())
                .timeout(startTime, req.timeout());

            if (req.responseProgress != null) { // set response progress listener
                // progress counts decoded entity bytes; a transport Content-Length on a compressed response is
                // in different units, so treat the length as unknown rather than report a bogus percentage
                int progressLength = contentEncoded ? -1 : res.contentLength;
                res.bodyStream.onProgress(progressLength, successful, req.responseProgress, res);
            }
        } else {
            res.byteData = DataUtil.emptyByteBuffer();
            // an empty entity (explicit zero length, or a HEAD request that delivers no body) has no body
            // stream to read, yet the caller still needs a single determinable completion event rather than
            // no progress at all; an unsuccessful status still never signals completion
            if (req.responseProgress != null)
                req.responseProgress.onProgress(0, 0, successful ? 100f : 0f, res);
        }
    } catch (IOException e) {
        if (res != null) res.safeClose(); // will be non-null if got to conn
        throw e;
    } finally {
        req.executing.unlock();

        // detach any thread local auth delegate
        if (req.authenticator != null)
            AuthenticationHandler.handler.remove();
    }

    res.executed = true;
    return res;
}

@Override
public int statusCode() {
    return statusCode;
}

@Override
public String statusMessage() {
    return statusMessage;
}

@Override @Nullable
public String charset() {
    return charset;
}

@Override
public Response charset(String charset) {
    this.charset = charset;
    return this;
}

@Override @Nullable
public String contentType() {
    return contentType;
}

/** Called from parse() or streamParser(), validates and prepares the input stream, and aligns common settings. */
private ControllableInputStream prepareParse() {
    Validate.isTrue(executed, "Request must be executed (with .execute(), .get(), or .post() before parsing response");
    ControllableInputStream stream = bodyStream;
    if (byteData != null) { // bytes have been read in to the buffer, parse that
        ByteArrayInputStream bytes = new ByteArrayInputStream(byteData.array(), 0, byteData.limit());
        stream = ControllableInputStream.wrap(bytes, 0); // no max
        inputStreamRead = false; // ok to reparse if in bytes
    }
    Validate.isFalse(inputStreamRead, "Input stream already read and parsed, cannot re-read.");

